import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {dashboardSurfaceAppBuilder} from './config/app-builder'

import {pullsDashboardSurfaceLayoutRoute} from './routes/pulls-dashboard-surface-layout-route'
import {PullsDashboardSurfaceLayoutComponent} from './routes/PullsDashboardSurfaceLayout'
import {pullsDashboardInboxRoute} from './routes/pulls-dashboard-inbox-route'
import {PullsDashboardInboxComponent} from './routes/PullsDashboardInbox'
import {pullsDashboardSurfaceContentRoute} from './routes/pulls-dashboard-surface-content-route'
import {PullsDashboardSurfaceContentComponent} from './routes/PullsDashboardSurfaceContent'
import {PullsDashboardSurfaceRedirect} from './routes/PullsDashboardSurfaceRedirect'
import {PullsDashboardInboxRedirect} from './routes/PullsDashboardInboxRedirect'
import {PullsDashboardSurfaceLegacyRedirects} from './routes/PullsDashboardSurfaceLegacyRedirects'
import {DashboardRouteErrorBoundary} from './components/shared/DashboardRouteErrorBoundary'
import {isFeatureEnabled} from '@github-ui/feature-flags'

export const dashboardSurfaceApp = dashboardSurfaceAppBuilder.createDataRouterAppFromRoutes(() => {
  const isInboxEnabled = isFeatureEnabled('pulls_dashboard_inbox')
  return [
    pullsDashboardSurfaceLayoutRoute.toRoute({
      Component: PullsDashboardSurfaceLayoutComponent,
      ErrorBoundary: DashboardRouteErrorBoundary,
      children: [
        ...(isInboxEnabled ? [] : [{index: true, Component: PullsDashboardSurfaceRedirect}]),
        {path: 'mentioned', Component: PullsDashboardSurfaceLegacyRedirects},
        {path: 'review-requested', Component: PullsDashboardSurfaceLegacyRedirects},
        {path: 'inbox', Component: PullsDashboardInboxRedirect},
        pullsDashboardSurfaceContentRoute.toRoute({
          Component: PullsDashboardSurfaceContentComponent,
          ErrorBoundary: DashboardRouteErrorBoundary,
        }),
        pullsDashboardInboxRoute.toRoute({
          Component: PullsDashboardInboxComponent,
          ErrorBoundary: DashboardRouteErrorBoundary,
        }),
      ],
    }),
  ]
})
registerDataRouterApp(dashboardSurfaceApp)
