import {PULLS_PATH} from './routes'
import {
  DeferredCategory,
  StatusCheckState,
  type DashboardSectionConfig,
  type StatusCheckRollup,
} from '../types/routes-types'

import type {LabelProps} from '@primer/react'
import type {Icon} from '@primer/octicons-react'
import {CheckCircleFillIcon, XCircleFillIcon} from '@primer/octicons-react'

export function getPullsSearchHref(query: string) {
  const search = new URLSearchParams({q: query}).toString()
  return `${PULLS_PATH}?${search}`
}

export interface CategoryDisplay {
  label: string
  variant: LabelProps['variant']
  icon?: Icon
  iconColor?: string
  iconColorClass?: string
}

const CATEGORY_MAP: Record<string, CategoryDisplay> = {
  CHANGES_REQUESTED: {
    label: 'Changes requested',
    variant: 'attention',
    icon: XCircleFillIcon,
    iconColor: 'var(--fgColor-danger)',
    iconColorClass: 'danger',
  },
  CI_FAILING: {
    label: 'Checks failing',
    variant: 'danger',
    icon: XCircleFillIcon,
    iconColor: 'var(--fgColor-danger)',
    iconColorClass: 'danger',
  },
  READY_TO_MERGE: {label: 'Ready to merge', variant: 'success'},
  AWAITING_REVIEW: {label: 'Awaiting approval', variant: 'attention'},
  MERGE_QUEUE: {label: 'Queued', variant: 'attention'},
}

const FALLBACK_CATEGORY: CategoryDisplay = {label: 'Action needed', variant: 'secondary'}

export function getCategoryDisplay(category: DeferredCategory): CategoryDisplay {
  return CATEGORY_MAP[category] ?? FALLBACK_CATEGORY
}

const OPTIONAL_CHECKS_FAILING: CategoryDisplay = {
  label: 'Able to merge',
  variant: 'attention',
  icon: CheckCircleFillIcon,
  iconColor: 'var(--fgColor-muted)',
  iconColorClass: 'neutral',
}

/**
 * Returns a composite category display when the server-assigned category
 * doesn't fully capture the PR state. Specifically, when a PR is categorised
 * as READY_TO_MERGE but its CI checks are failing, we override the display
 * to surface the failing-checks signal instead of the green "Ready to merge".
 * Uses the 'Able to Merge'
 */
export function getCompositeCategoryDisplay(
  category: DeferredCategory,
  statusCheckRollup?: StatusCheckRollup,
): CategoryDisplay {
  if (category === DeferredCategory.ReadyToMerge && statusCheckRollup?.state === StatusCheckState.Failure) {
    return OPTIONAL_CHECKS_FAILING
  }
  return getCategoryDisplay(category)
}

