import {isFeatureEnabled} from '@github-ui/feature-flags'

// !! CAUTION !! If you modify these default queries, they must also be updated on the backend: packages/dashboard_surface/app/lib/dashboard_surface/payloads/sidebar_links.rb
export function queryMap(): Record<string, string> {
  const addArchivedFalse = isFeatureEnabled('pulls_add_archived_false')
  const addUpdatedDesc = isFeatureEnabled('dashboard_add_updated_desc')

  function buildQuery(base: string): string {
    let q = base
    if (addArchivedFalse) q += ' archived:false'
    if (addUpdatedDesc) q += ' sort:updated-desc'
    return q
  }

  return {
    authored: buildQuery('is:pr author:@me state:open'),
    assigned: buildQuery('is:pr assignee:@me state:open'),
    involves: buildQuery('is:pr involves:@me state:open'),
    'on-my-behalf': buildQuery('is:pr author:@copilot assignee:@me state:open'),
    reviews: buildQuery('is:pr review-requested:@me state:open'),
  }
}

export const queryResolver = ({
  searchParams,
  params,
}: {
  searchParams: URLSearchParams
  params: {mode?: string}
}): string => {
  const map = queryMap()
  let q = ''
  if (searchParams.get('q')) {
    q = searchParams.get('q') as string
  } else if (params.mode && map[params.mode]) {
    q = map[params.mode] as string
  }
  return q
}
