import {useLocation, useParams} from '@github-ui/react-router'
import {useAnalytics} from '@github-ui/use-analytics'
import {useNavigate} from '@github-ui/use-navigate'
import {useEffect, useRef, useState} from 'react'
import {isExplicitIssueQuery} from '../helpers/is-explicit-issue-query'
import {queryResolver} from '../helpers/query-resolver'
import {PULLS_PATH} from '../constants/routes'

interface UseListResultsParams {
  defaultFilterValue?: string
}

interface FetchResultsParams {
  q: string
  page: number
  sidebarLinkId?: string
}

/**
 * Hook to manage URL-based list results state.
 * Handles query parameters, pagination, and navigation for list results.
 *
 * @param params Configuration object
 * @param params.defaultFilterValue Default filter value to use when no query param is present
 * @returns An object containing:
 *   - fetchedQuery: The active query (empty string if explicitly cleared)
 *   - currentPage: The current page number from URL
 *   - fetchResults: Function to navigate to new search results
 *   - locationSidebarLinkId: The sidebar link path
 */
export function useListResults({defaultFilterValue = ''}: UseListResultsParams) {
  const navigate = useNavigate()
  const location = useLocation()
  const {sendAnalyticsEvent} = useAnalytics()

  const {mode} = useParams<{mode: string}>()

  const currentParams = new URLSearchParams(location.search)
  const [isEmptyQuery, setIsEmptyQuery] = useState(false)

  const query = queryResolver({searchParams: currentParams, params: {mode}})
  const fetchedQuery = isEmptyQuery ? '' : query

  const prevQueryRef = useRef(query)
  useEffect(() => {
    if (prevQueryRef.current !== query) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- We cannot do this with useSyncedState nor directly from the render
      setIsEmptyQuery(false)
      prevQueryRef.current = query
    }
  }, [query])

  const currentPage = Number(currentParams.get('page') || 1)

  function fetchResults({q, page, sidebarLinkId}: FetchResultsParams) {
    if (isExplicitIssueQuery(q)) {
      sendAnalyticsEvent('pull-requests.search', 'IS_ISSUE', {query: q})

      navigate(`/issues?q=${encodeURIComponent(q)}`)
      return
    }

    sendAnalyticsEvent('pull-requests.search', 'LIST_RESULTS', {query: q})

    if (!q) {
      setIsEmptyQuery(true)
      return
    }

    // Don't reset isEmptyQuery here - let the useEffect handle it when fetchedQuery changes.
    // Resetting it synchronously before navigation causes old results to flash.

    const navigateParams = new URLSearchParams()

    if (q && q !== defaultFilterValue) {
      navigateParams.set('q', q)
    }

    if (page > 1) {
      navigateParams.set('page', page.toString())
    }

    const search = navigateParams.toString()
    const navigationState = location.state as {sidebarLinkId?: string} | null
    const effectiveSidebarLinkId = sidebarLinkId !== undefined ? sidebarLinkId : navigationState?.sidebarLinkId
    const pathname = mode ? `${PULLS_PATH}/${mode}` : PULLS_PATH
    navigate(
      {
        pathname,
        search: search ? `?${search}` : '',
      },
      effectiveSidebarLinkId ? {state: {sidebarLinkId: effectiveSidebarLinkId}} : undefined,
    )
  }

  return {
    fetchedQuery,
    currentPage,
    fetchResults,
    mode,
    locationSidebarLinkId: mode,
  }
}
