import {AnalyticsProvider} from '@github-ui/analytics-provider'
import {Filter} from '@github-ui/filter'
import {ContextualGlobalSsoBanner} from '@github-ui/global-sso-banner/contextual'
import {PreviewCardOutlet} from '@github-ui/preview-card'
import {ReposSelector} from '@github-ui/repos-selector'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useLocation} from '@github-ui/react-router'
import {DashboardSidebar} from '@github-ui/shared-dashboard-sidebar/DashboardSidebar'
import {useMemo} from 'react'
import {pullsDashboardSurfaceLayoutRoute} from './pulls-dashboard-surface-layout-route'
import {SharedHeader} from '../components/shared/SharedHeader'
import {SharedLayout} from '../components/shared/SharedLayout'
import {
  PullsDashboardSurfaceStateProvider,
  usePullsDashboardSurfaceStateContext,
} from '../contexts/PullsDashboardSurfaceStateContext'
import {usePullsDashboardSurfaceLayoutState} from '../hooks/use-pulls-dashboard-surface-layout-state'
import {ShortcutEditingHeader} from '@github-ui/saved-views'
import {InboxPrAgeFilter} from '../components/lists/pulls/InboxPrAgeFilter'
import {isOnInboxPath} from '../helpers/is-on-inbox'

import type {PullsDashboardLayoutPayload} from '../types/routes-types'
import {pullsDashboardSurfaceContentRoute} from './pulls-dashboard-surface-content-route'

export function PullsDashboardSurfaceLayoutComponent() {
  const {data: payload, isPending: isLoading} = useRouteQuery(pullsDashboardSurfaceLayoutRoute, 'mainQuery')

  return <PullsDashboardSurfaceLayoutRoot payload={payload} isLoading={isLoading} />
}

function PullsDashboardSurfaceLayoutRoot({
  payload,
  isLoading,
}: {
  payload: PullsDashboardLayoutPayload | undefined
  isLoading: boolean
}) {
  return (
    <AnalyticsProvider
      appName="pulls-dashboard-surface"
      category="Dashboard Surface"
      metadata={{page: 'pulls-dashboard'}}
    >
      <ContextualGlobalSsoBanner />
      <div data-testid="pulls-dashboard-surface-layout" data-issue-and-pr-hovercards-enabled>
        {payload && (
          <PullsDashboardSurfaceStateProvider payload={payload} isLoading={isLoading}>
            <PullsDashboardSurfaceLayout />
          </PullsDashboardSurfaceStateProvider>
        )}
        <PreviewCardOutlet />
      </div>
    </AnalyticsProvider>
  )
}

function PullsDashboardSurfaceLayout() {
  const {
    sidebarLinks,
    savedViews,
    selectedSidebarLink,
    editing,
    deleting,
    methods,
    pullsFilterProps,
    inboxPickerProps,
  } = usePullsDashboardSurfaceLayoutState()

  const {fetchedQuery, isLoading, maxPrAge} = usePullsDashboardSurfaceStateContext()
  const {pathname} = useLocation()
  const isOnInbox = isOnInboxPath({pathname})

  const savedViewsEnabled = true
  const feedbackDialogEnabled = true

  const visibleLinks = useMemo(() => sidebarLinks, [sidebarLinks])
  const generateLinkPath = (path: string | undefined, query?: string) => {
    if (query) {
      // We'll add search: query to the path for saved views only
      return pullsDashboardSurfaceContentRoute.generatePath({mode: path || ''}, {search: `?q=${query}`})
    } else {
      return pullsDashboardSurfaceContentRoute.generatePath({mode: path || ''})
    }
  }

  return (
    <SharedLayout
      header={
        editing.shortcut ? (
          <ShortcutEditingHeader
            renderFilter={filterProps => (
              <Filter {...filterProps} {...pullsFilterProps} data-testid="pulls-filter-component" />
            )}
            onSave={editing.saveAndDismiss}
            onDismiss={editing.dismiss}
            shortcut={editing.shortcut}
            setShortcutValue={editing.setValue}
            isSaving={editing.isSaving}
            errorMessage={editing.errorMessage}
          />
        ) : (
          <SharedHeader
            dashboardType="pull-requests"
            links={visibleLinks}
            selectedLink={selectedSidebarLink}
            onSelectLink={methods.selectSidebarLink}
            showFeedbackDialog={feedbackDialogEnabled}
            feedbackSubject={isOnInbox ? 'pulls_inbox_feedback' : 'pulls_dashboard_feedback'}
            feedbackPlaceholderText="Tell us your feedback on the new pull request experience"
            rightSideContent={
              isOnInbox && inboxPickerProps ? (
                <div className="d-flex flex-wrap gap-2" data-testid="pulls-inbox-picker-filter">
                  <ReposSelector
                    selectionVariant="multiple"
                    selectAllOption={false}
                    currentSelection={inboxPickerProps.repoSelection}
                    repositoryLoader={inboxPickerProps.repoLoader}
                    onSelect={inboxPickerProps.selectRepos}
                  />
                  <InboxPrAgeFilter
                    selectedMaxPrAge={maxPrAge}
                    onMaxPrAgeChange={inboxPickerProps.handleMaxPrAgeChange}
                  />
                </div>
              ) : undefined
            }
            filter={!isOnInbox ? <Filter {...pullsFilterProps} data-testid="pulls-filter-component" /> : undefined}
            savedViews={savedViews}
            showSavedViews={savedViewsEnabled}
            onCreateView={methods.createShortcut}
            onEditView={methods.editShortcut}
            onDeleteView={deleting.deleteShortcut}
            onUpdateView={methods.updateShortcut}
            isViewModified={!isLoading && fetchedQuery !== selectedSidebarLink?.query}
            deleteErrorMessage={deleting.errorMessage}
            generateLinkPath={generateLinkPath}
          />
        )
      }
      sidebar={
        <DashboardSidebar
          dashboardType="pull-requests"
          links={visibleLinks}
          selectedLink={selectedSidebarLink?.id || ''}
          onSelectLink={methods.selectSidebarLink}
          savedViews={savedViews}
          showSavedViews={savedViewsEnabled}
          onCreateView={methods.createShortcut}
          generateLinkPath={generateLinkPath}
        />
      }
    />
  )
}
