import {debounce} from '@github/mini-throttle'
import {announce} from '@github-ui/aria-live'
import {useEffect, useRef} from 'react'
import {getScreenReaderMessage} from '../helpers/screen-reader-helpers'
import {dashboardTypeLabels, type DashboardTypes} from '@github-ui/shared-dashboard-sidebar/types/dashboard-types'
import type {EmptyMessageParams} from '../types/ui-types'
import {defaultSortingOptions} from '../constants/pulls-sorting'

function getEmptyMessage({dashboardType, filtered, currentPage, pageCount, errorMessage}: EmptyMessageParams): {
  heading: string
  description?: string
} {
  if (errorMessage) {
    return {heading: 'Invalid query', description: errorMessage}
  }

  if (pageCount > 0 && currentPage > pageCount) {
    return {heading: `No more ${dashboardTypeLabels[dashboardType]}.`, description: 'Visit a lower page.'}
  }

  if (filtered) {
    return {
      heading: `No ${dashboardTypeLabels[dashboardType]} matched your search.`,
      description: 'Try a different search query.',
    }
  }

  return {heading: 'Enter a query to start searching.'}
}

/**
 * Hook to manage screen reader announcements.
 * Announces search results and empty states to screen reader users.
 * @param dashboardType - The type of dashboard (e.g., issues, pull requests).
 * @param isFetching - Whether a fetch is currently in progress.
 * @param currentPage - The current page number.
 * @param fetchedQuery - The query string that was fetched.
 * @param defaultSortingKey - The default sorting key to use.
 * @param resultCount - The number of results returned from the search.
 * @param pageCount - The total number of pages available for the current query.
 * @param errorMessage - Optional error message to announce when the query is invalid or results in an error.
 * @returns An object containing the empty messages for display.
 */
export function useScreenReaderAnnouncements(
  dashboardType: DashboardTypes,
  isFetching: boolean,
  currentPage: number,
  fetchedQuery: string,
  defaultSortingKey: string,
  resultCount: number,
  pageCount: number,
  errorMessage?: string,
) {
  const emptyMessages = getEmptyMessage({
    dashboardType,
    filtered: !!fetchedQuery,
    currentPage,
    pageCount,
    errorMessage,
  })

  const message = getScreenReaderMessage(
    dashboardType,
    defaultSortingOptions,
    defaultSortingKey,
    () => emptyMessages,
    isFetching,
    currentPage,
    fetchedQuery,
    resultCount,
    pageCount,
  )

  const debouncedAnnounceRef = useRef(debounce(announce, 300))

  useEffect(() => {
    const debouncedAnnounce = debouncedAnnounceRef.current

    if (message) debouncedAnnounce(message)

    return () => {
      debouncedAnnounce.cancel()
    }
  }, [message])

  return {emptyMessages}
}
