import {queryFnFetch} from '@github-ui/react-core/future/query-fn-fetch'

import {dashboardSurfaceAppBuilder} from '../config/app-builder'
import {PULLS_PATH, PULLS_INBOX_PATH} from '../constants/routes'
import type {PullsDashboardSurfacePayload, SectionDataResult} from '../types/routes-types'

interface InboxSectionQueryResponse {
  payload?: {
    pullsInboxSurfaceContentRoute?: PullsDashboardSurfacePayload
  }
}

function extractSectionData(json: InboxSectionQueryResponse): SectionDataResult {
  const payload = json.payload?.pullsInboxSurfaceContentRoute
  if (!payload) {
    throw new Error('Unexpected response shape: missing pullsInboxSurfaceContentRoute')
  }
  return {results: payload.results, totalCount: payload.pageInfo.totalCount}
}

function sectionQueryDeps(sectionId: string) {
  return ({searchParams}: {searchParams: URLSearchParams}) => ({
    pathname: `${PULLS_INBOX_PATH}/queries`,
    searchParams: {
      q: `${sectionId} ${searchParams.get('q') || ''}`.trim(),
      max_pr_age: searchParams.get('max_pr_age') || '1y',
    },
  })
}

async function sectionQueryFn(queryKey: Parameters<typeof queryFnFetch>[0]): Promise<SectionDataResult> {
  const json = await queryFnFetch<InboxSectionQueryResponse>(queryKey)
  return extractSectionData(json)
}

export const INBOX_SECTION_QUERY_NAMES = {
  'review-requested': 'sectionReviewRequested',
  'team-review-requested': 'sectionTeamReviewRequested',
  'needs-action': 'sectionNeedsAction',
  'ready-to-merge': 'sectionReadyToMerge',
  'merge-queue': 'sectionMergeQueue',
} as const

export type InboxSectionQueryName = (typeof INBOX_SECTION_QUERY_NAMES)[keyof typeof INBOX_SECTION_QUERY_NAMES]

export const pullsDashboardInboxRoute = dashboardSurfaceAppBuilder.createQueryRouteConfig('pullsDashboardInboxRoute', {
  path: PULLS_PATH,
  index: true,
  queries: [
    {
      queryName: 'sectionReviewRequested',
      queryDeps: sectionQueryDeps('review-requested'),
      queryFn: sectionQueryFn,
    },
    {
      queryName: 'sectionTeamReviewRequested',
      queryDeps: sectionQueryDeps('team-review-requested'),
      queryFn: sectionQueryFn,
    },
    {
      queryName: 'sectionNeedsAction',
      queryDeps: sectionQueryDeps('needs-action'),
      queryFn: sectionQueryFn,
    },
    {
      queryName: 'sectionReadyToMerge',
      queryDeps: sectionQueryDeps('ready-to-merge'),
      queryFn: sectionQueryFn,
    },
    {
      queryName: 'sectionMergeQueue',
      queryDeps: sectionQueryDeps('merge-queue'),
      queryFn: sectionQueryFn,
    },
  ],
})
