import {SortingDropdown} from '@github-ui/dashboard-sorting-dropdown/SortingDropdown'
import {ListView} from '@github-ui/list-view'
import {ListViewDensityToggle} from '@github-ui/list-view/ListViewDensityToggle'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import {PullsListEmptyMessage, type PullsListEmptyMessageProps} from './PullsListEmptyMessage'
import {PullsListItem} from './PullsListItem'
import type {PageInfo, PullItem} from '../../../types/routes-types'
import {DisplayMode} from '../../../types/ui-types'

import styles from './PullsList.module.css'
import {DEFAULT_SORTING_KEY, defaultSortingOptions} from '../../../constants/pulls-sorting'

interface PullsListProps {
  pulls: PullItem[]
  pageInfo: PageInfo
  compactMode: boolean
  onCompactModeChange: (value: boolean) => void
  onSortingItemSelect: (key: string) => void
  pullsEmptyListMessages: PullsListEmptyMessageProps
  sortingItemSelected?: string
}

export function PullsList({
  pulls,
  pageInfo,
  compactMode,
  onCompactModeChange,
  sortingItemSelected,
  onSortingItemSelect,
  pullsEmptyListMessages,
}: PullsListProps) {
  const resultText = pageInfo.totalCount === 1 ? 'result' : 'results'

  return (
    <ListView
      title="Pull requests"
      titleHeaderTag="h2"
      className={styles.pullsListContainer}
      onVariantChange={value => onCompactModeChange(value === DisplayMode.Compact)}
      variant={compactMode ? DisplayMode.Compact : DisplayMode.Default}
      metadata={
        <ListViewMetadata
          title={
            <span data-testid="results-count">
              {pageInfo.totalCount} {resultText}
            </span>
          }
          densityToggle={<ListViewDensityToggle />}
        >
          <div className="mr-2">
            <SortingDropdown
              sortingItemSelected={sortingItemSelected || ''}
              onSortingItemSelect={onSortingItemSelect}
              defaultSortingKey={DEFAULT_SORTING_KEY}
              sortingOptions={defaultSortingOptions}
              directionRestrictedKeys={['relevance']}
              sortFieldsRequireDescSuffix
            />
          </div>
        </ListViewMetadata>
      }
    >
      {pulls.length > 0 ? (
        <PullsListItem pulls={pulls} />
      ) : (
        <li>
          <PullsListEmptyMessage {...pullsEmptyListMessages} />
        </li>
      )}
    </ListView>
  )
}
