import {useMemo} from 'react'
import {useRouteQuery, useSuspenseRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {pullsDashboardSurfaceContentRoute} from '../routes/pulls-dashboard-surface-content-route'
import type {PullsDashboardEnrichedDataPayload} from '../types/routes-types'

export function useEnrichedPulls(): PullsDashboardEnrichedDataPayload {
  const {data: payload} = useSuspenseRouteQuery(pullsDashboardSurfaceContentRoute, 'mainQuery')

  const {
    data: deferredData,
    isPending: isPending,
    isError,
  } = useRouteQuery(pullsDashboardSurfaceContentRoute, 'deferred')

  const dataResults = payload?.results
  const deferredResults = deferredData?.payload?.pullsDashboardSurfaceContentDeferredData.results

  const enrichedPullsData = useMemo(() => {
    return dataResults.map(pull => {
      const deferredPull = deferredResults?.find(deferredPullData => deferredPullData.id === pull.id)
      return {
        ...pull,
        reviewDecisionState: deferredPull?.reviewDecisionState,
        statusCheckRollup: deferredPull?.statusCheckRollup,
      }
    })
  }, [deferredResults, dataResults])

  return {
    pulls: enrichedPullsData,
    pageInfo: payload?.pageInfo,
    isPending,
    isError,
  }
}
