import {Table} from '@primer/react/experimental'

import styles from './DashboardSection.module.css'

interface DashboardSectionSkeletonProps {
  name: string
  numItems: number
}

const skeletonColumns = [
  {header: 'Pull request', id: 'title'},
  {header: 'Status', id: 'category'},
  {header: 'Comments', id: 'commentCount'},
  {header: 'Checks', id: 'statusCheckRollup'},
  {header: 'Review', id: 'reviewDecisionState'},
]

export function DashboardSectionSkeleton({name, numItems}: DashboardSectionSkeletonProps) {
  const titleId = `inbox-skeleton-${name.toLowerCase().replace(/\s+/g, '-')}`

  return (
    <section aria-label={`Loading ${name}`} data-testid="inbox-section-skeleton">
      <h2 id={titleId} className="h4">
        {name}
      </h2>
      <div className={styles.tableContainer}>
        <Table.Container>
          <Table.Skeleton aria-labelledby={titleId} rows={numItems} columns={skeletonColumns} cellPadding="normal" />
        </Table.Container>
      </div>
    </section>
  )
}
