import {useMemo} from 'react'
import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'
import {PullRequestStateIcons} from '@github-ui/issue-pr-state/Icons'
import {useAnalytics} from '@github-ui/use-analytics'
import {CheckCircleFillIcon, CommentIcon, DashIcon} from '@primer/octicons-react'
import {Button, Link, RelativeTime} from '@primer/react'
import {DataTable, Table} from '@primer/react/experimental'
import {clsx} from 'clsx'

import {DashboardSectionSkeleton} from './DashboardSectionSkeleton'
import {DashboardBlankslate} from './DashboardBlankslate'
import {reviewDecisionCompact, statusCheckColumnDisplay} from './PullsDescriptionHelpers'
import type {DashboardSectionConfig, EnrichedPull} from '../../../types/routes-types'
import styles from './DashboardSection.module.css'
import {getCompositeCategoryDisplay} from '../../../constants/inbox-sections'

function CenteredCell({children, className}: {children: React.ReactNode; className?: string}) {
  return <span className={clsx(styles.centeredCell, styles.cell, className)}>{children}</span>
}

function LeftAlignedCell({children, className}: {children: React.ReactNode; className?: string}) {
  return <span className={clsx(styles.leftAlignedCell, styles.cell, className)}>{children}</span>
}

interface DashboardSectionProps {
  config: DashboardSectionConfig
  enrichedPulls: EnrichedPull[]
  totalCount: number
  hasMore: boolean
  isPending: boolean
  isError: boolean
  isDeferredError: boolean
  loadMore: () => void
}

export function DashboardSection({
  config,
  enrichedPulls,
  totalCount,
  hasMore,
  isPending,
  isError,
  isDeferredError,
  loadMore,
}: DashboardSectionProps) {
  const sectionResultLimit = 25
  const {sendAnalyticsEvent} = useAnalytics()
  const getHovercardAttributesForType = useGetHovercardAttributesForType()

  const columns = useMemo(
    () => [
      {
        header: 'Title',
        field: 'title' as const,
        width: 'grow' as const,
        renderCell: (row: EnrichedPull) => {
          const PRStateIcon = row.displayState
            ? PullRequestStateIcons[row.displayState as keyof typeof PullRequestStateIcons]
            : undefined
          const [owner, repo] = row.repoNameWithOwner.split('/')
          const hovercardProps = getHovercardAttributesForType('pull_request', {
            owner,
            repo,
            pullRequestNumber: row.number,
          })
          return (
            <span className={styles.titleCellContainer}>
              <span className={styles.titleCell}>
                <span className={styles.stateIcon}>
                  {PRStateIcon ? (
                    <PRStateIcon />
                  ) : (
                    <DashIcon size={16} className="color-fg-muted" data-testid="fallback-pr-state-icon" />
                  )}
                </span>
                <Link
                  href={row.permalink}
                  className={styles.titleLink}
                  onClick={() =>
                    sendAnalyticsEvent('pull-requests.click', 'LIST_ITEM_TITLE', {displayState: row.displayState})
                  }
                  {...hovercardProps}
                >
                  {row.title}
                </Link>
                <span className={styles.subtitle}>
                  {row.repoNameWithOwner}#{row.number} • {row.author.displayLogin} • Updated{' '}
                  <RelativeTime date={new Date(row.updatedAt)} />
                </span>
              </span>
            </span>
          )
        },
      },
      {
        header: 'Status',
        field: 'category' as const,
        width: 'auto' as const,
        renderCell: (row: EnrichedPull) => {
          if (!row.category) return null
          const display = getCompositeCategoryDisplay(row.category, row.statusCheckRollup)
          const IconComponent = display.icon
          return (
            <span className={styles.categoryBadge} data-variant={display.variant}>
              {IconComponent ? (
                <span style={display.iconColor ? {color: display.iconColor} : undefined}>
                  <IconComponent size={12} data-testid="status-indicator" aria-label={`${display.label} indicator`} />
                </span>
              ) : display.variant === 'success' ? (
                <CheckCircleFillIcon
                  size={12}
                  className={styles.categoryBadgeSuccessIcon}
                  data-testid="status-indicator"
                  aria-label="Ready to merge indicator"
                />
              ) : (
                <span className={styles.categoryBadgeDot} data-testid="status-indicator" />
              )}
              {display.label}
            </span>
          )
        },
      },
      {
        header: 'Comments',
        field: 'commentCount' as const,
        width: 'auto' as const,
        renderCell: (row: EnrichedPull) => {
          if (row.commentCount === 0)
            return (
              <LeftAlignedCell>
                <DashIcon size={16} className="color-fg-muted tmp-mr-4" />
              </LeftAlignedCell>
            )
          return (
            <LeftAlignedCell>
              <CommentIcon size={16} /> {row.commentCount}
            </LeftAlignedCell>
          )
        },
      },
      {
        header: 'Checks',
        field: 'statusCheckRollup' as const,
        width: 'auto' as const,
        renderCell: (row: EnrichedPull) => {
          if (!row.statusCheckRollup)
            return (
              <LeftAlignedCell>
                <DashIcon size={16} className="color-fg-muted" />
              </LeftAlignedCell>
            )
          return <LeftAlignedCell>{statusCheckColumnDisplay(row.statusCheckRollup)}</LeftAlignedCell>
        },
      },
      {
        header: 'Review',
        field: 'reviewDecisionState' as const,
        width: 'auto' as const,
        renderCell: (row: EnrichedPull) => {
          if (!row.reviewDecisionState)
            return (
              <CenteredCell>
                <DashIcon size={16} className="color-fg-muted" />
              </CenteredCell>
            )
          return <CenteredCell>{reviewDecisionCompact(row.reviewDecisionState)}</CenteredCell>
        },
      },
    ],
    [getHovercardAttributesForType, sendAnalyticsEvent],
  )

  if (isPending) {
    return <DashboardSectionSkeleton name={config.name} numItems={config.maxItems} />
  }

  if (isError) {
    return (
      <section aria-label={config.name}>
        <h2 className="h4 mb-2">{config.name}</h2>
        <DashboardBlankslate variant="error" />
      </section>
    )
  }

  const titleId = `inbox-section-${config.id}`
  const hasReachedResultLimit =
    !hasMore && enrichedPulls.length >= sectionResultLimit && totalCount >= sectionResultLimit

  if (config.id === 'merge-queue' && totalCount === 0) return null

  return (
    <section aria-label={config.name} data-testid={`inbox-section-${config.id}`}>
      <h2 id={titleId} className="h4">
        {config.name}
      </h2>
      {isDeferredError && (
        <p className="f6 color-fg-muted mt-2 mb-0" role="status">
          Some status details could not be loaded.
        </p>
      )}
      <div className={styles.tableContainer}>
        {enrichedPulls.length > 0 ? (
          <>
            <Table.Container>
              <DataTable aria-labelledby={titleId} data={enrichedPulls} columns={columns} cellPadding="normal" />
            </Table.Container>
          </>
        ) : (
          <DashboardBlankslate variant="empty" />
        )}
      </div>
      {hasMore && (
        <div className={styles.loadMoreContainer}>
          <Button type="button" onClick={loadMore}>
            Load more
          </Button>
        </div>
      )}
      {hasReachedResultLimit && <p className="f6 color-fg-muted mt-2 mb-0">Results are limited to 25.</p>}
    </section>
  )
}
