import {useAnalytics} from '@github-ui/use-analytics'
import {GitPullRequestIcon} from '@primer/octicons-react'
import {Link} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'

export interface PullsListEmptyMessageProps {
  heading: string
  description?: string
}

export function PullsListEmptyMessage({heading, description}: PullsListEmptyMessageProps) {
  const {sendAnalyticsEvent} = useAnalytics()

  return (
    <Blankslate data-testid="pulls-empty-state">
      <Blankslate.Visual>
        <GitPullRequestIcon size={24} />
      </Blankslate.Visual>

      <Blankslate.Heading>{heading}</Blankslate.Heading>
      <Blankslate.Description>
        <span>{description ?? 'Try a different search query.'}</span>{' '}
        <Link
          inline
          href="https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/filtering-and-searching-issues-and-pull-requests"
          onClick={() => sendAnalyticsEvent('pull-requests.click', 'EMPTY_STATE', {label: 'learn-more-link'})}
        >
          Learn more about searching and filtering pull requests.
        </Link>
      </Blankslate.Description>
    </Blankslate>
  )
}
