import {createContext, use, useMemo, useState} from 'react'
import {useLocation} from '@github-ui/react-router'
import {isOnInboxPath} from '../helpers/is-on-inbox'
import {queryMap} from '../helpers/query-resolver'
import type {ReactNode} from 'react'

import type {PullsDashboardLayoutPayload, PullsInboxMaxAge as PullsInboxMaxAgeType} from '../types/routes-types'
import {PullsInboxMaxAge} from '../types/routes-types'
import {useListResults} from '../hooks/use-list-results'

interface PullsDashboardSurfaceStateContextValue {
  // Payload
  payload: PullsDashboardLayoutPayload
  // Shared state
  fetchedQuery: string
  currentPage: number
  locationSidebarLinkId?: string
  // Loading state from route query
  isLoading: boolean
  // Inbox max PR age filter
  maxPrAge: PullsInboxMaxAgeType
  setMaxPrAge: (maxPrAge: PullsInboxMaxAgeType) => void
  // Shared methods
  fetchResults: (args: {q: string; page: number; sidebarLinkId?: string}) => void
}

const PullsDashboardSurfaceStateContext = createContext<PullsDashboardSurfaceStateContextValue | null>(null)

export function PullsDashboardSurfaceStateProvider({
  children,
  payload,
  isLoading,
}: {
  children: ReactNode
  payload: PullsDashboardLayoutPayload
  isLoading: boolean
}) {
  const {pathname} = useLocation()
  const isOnInbox = isOnInboxPath({pathname})

  const {fetchedQuery, currentPage, fetchResults, locationSidebarLinkId} = useListResults({
    defaultFilterValue: isOnInbox ? '' : queryMap().authored,
  })

  const [maxPrAge, setMaxPrAge] = useState<PullsInboxMaxAgeType>(payload.filters?.maxPrAge ?? PullsInboxMaxAge.OneMonth)

  const value: PullsDashboardSurfaceStateContextValue = useMemo(
    () => ({
      payload,
      fetchedQuery,
      currentPage,
      fetchResults,
      locationSidebarLinkId,
      isLoading,
      maxPrAge,
      setMaxPrAge,
    }),
    [payload, fetchedQuery, currentPage, fetchResults, locationSidebarLinkId, isLoading, maxPrAge, setMaxPrAge],
  )

  return <PullsDashboardSurfaceStateContext value={value}>{children}</PullsDashboardSurfaceStateContext>
}

export function usePullsDashboardSurfaceStateContext() {
  const context = use(PullsDashboardSurfaceStateContext)
  if (!context) {
    throw new Error('usePullsDashboardSurfaceStateContext must be used within a PullsDashboardSurfaceStateProvider')
  }
  return context
}
