import {RelativeTime} from '@primer/react'
import {ProfileReference} from '@github-ui/profile-reference'
import {StateType} from '../../../types/routes-types'

interface TimestampContainerProps {
  createdAt: Date
  updatedAt: Date
  prState: StateType
  author: string
  isAgent?: boolean
}

export const TimestampContainer = ({
  prState,
  author,
  createdAt,
  updatedAt,
  isAgent = false,
}: TimestampContainerProps) => {
  const hasBeenUpdated = createdAt.getTime() !== updatedAt.getTime()
  const isOpen = prState === StateType.Opened
  const isClosed = !isOpen

  return (
    <span data-testid="timestamp-container">
      <span>&middot; </span>
      <ProfileReference login={author} profileName={author} isAgent={isAgent} />
      <span> opened </span>
      <RelativeTime date={createdAt} />
      {isOpen && hasBeenUpdated && (
        <span>
          {' '}
          <span>&middot;</span> <span>Updated</span> <RelativeTime date={updatedAt} />
        </span>
      )}
      {isClosed && (
        <span>
          {' '}
          <span>&middot;</span> <span>Closed</span> <RelativeTime date={updatedAt} />
        </span>
      )}
    </span>
  )
}
