import {AlertIcon, InboxIcon} from '@primer/octicons-react'
import {Blankslate} from '@primer/react/experimental'

type DashboardBlankslateVariant = 'empty' | 'error'

const variants = {
  empty: {
    icon: InboxIcon,
    heading: 'All caught up',
    description: "When a pull request needs your review or attention, it'll appear here.",
  },
  error: {
    icon: AlertIcon,
    heading: 'Something went wrong',
    description: 'Failed to load pull requests. Try refreshing the page.',
  },
} as const

interface DashboardBlankslateProps {
  variant: DashboardBlankslateVariant
}

export function DashboardBlankslate({variant}: DashboardBlankslateProps) {
  const {icon: Icon, heading, description} = variants[variant]

  return (
    <div className="border border-color-muted rounded-2" role={variant === 'error' ? 'alert' : 'status'}>
      <Blankslate border={false} spacious={false}>
        <Blankslate.Visual>
          <Icon size={24} />
        </Blankslate.Visual>
        <Blankslate.Heading>{heading}</Blankslate.Heading>
        <Blankslate.Description>{description}</Blankslate.Description>
      </Blankslate>
    </div>
  )
}
