import {useCallback, useMemo} from 'react'
import {ErrorBoundary} from '@github-ui/react-core/error-boundary'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {DashboardSection} from '../components/lists/pulls/DashboardSection'
import {DashboardBlankslate} from '../components/lists/pulls/DashboardBlankslate'
import {inboxSections} from '../constants/inbox-sections'
import {usePullsDashboardSurfaceStateContext} from '../contexts/PullsDashboardSurfaceStateContext'
import {fetchSectionDeferredData} from '../helpers/section-fetchers'
import {useSectionData} from '../hooks/use-section-data'
import {pullsDashboardInboxRoute, INBOX_SECTION_QUERY_NAMES} from './pulls-dashboard-inbox-route'
import type {InboxSectionQueryName} from './pulls-dashboard-inbox-route'
import {isFeatureEnabled} from '@github-ui/feature-flags'

export function PullsDashboardInboxComponent() {
  const teamReviewRequestedEnabled = isFeatureEnabled('team_review_requested_by_user_filter')

  const visibleSections = useMemo(
    () =>
      teamReviewRequestedEnabled
        ? inboxSections
        : inboxSections.filter(section => section.id !== 'team-review-requested'),
    [teamReviewRequestedEnabled],
  )

  return (
    <div data-testid="pulls-dashboard-inbox" data-hpc className="tmp-pt-3">
      <div className="d-flex flex-column gap-4">
        {visibleSections.map(section => (
          <ErrorBoundary
            key={section.id}
            boundaryName={`InboxDashboardSection-${section.id}`}
            fallback={
              <section aria-label={section.name}>
                <h2 className="h4 mb-2">{section.name}</h2>
                <DashboardBlankslate variant="error" />
              </section>
            }
          >
            <InboxDashboardSection section={section} />
          </ErrorBoundary>
        ))}
      </div>
    </div>
  )
}

function InboxDashboardSection({section}: {section: (typeof inboxSections)[number]}) {
  const queryName = INBOX_SECTION_QUERY_NAMES[section.id as keyof typeof INBOX_SECTION_QUERY_NAMES]
  const {data, isPending, isError} = useRouteQuery(pullsDashboardInboxRoute, queryName as InboxSectionQueryName)

  const {
    payload: {inboxSectionQueries: inboxSectionQueriesFromLayout},
    fetchedQuery,
    maxPrAge,
  } = usePullsDashboardSurfaceStateContext()

  // Use layout-provided query override for deferred fetching (which stays client-side)
  const queryId = inboxSectionQueriesFromLayout?.[section.id] ?? section.id
  const scopedQuery = queryId + (fetchedQuery ? ` ${fetchedQuery}` : '')

  const fetchDeferred = useCallback(
    (results: Array<{id: number}>) =>
      fetchSectionDeferredData(
        scopedQuery,
        results.map(result => result.id),
      ),
    [scopedQuery],
  )

  const sectionData = useSectionData({
    sectionId: section.id,
    scopeKey: `${scopedQuery} ${maxPrAge}`,
    primaryData: data,
    isPrimaryPending: isPending,
    isPrimaryError: isError,
    fetchDeferred,
    maxItems: section.maxItems,
  })

  return <DashboardSection config={section} {...sectionData} />
}
