import {
  CheckCircleFillIcon,
  CheckIcon,
  ClockIcon,
  FileDiffIcon,
  NoEntryFillIcon,
  XCircleFillIcon,
  XIcon,
} from '@primer/octicons-react'
import {Tooltip} from '@primer/react'
import {ReviewDecisionState, StatusCheckState, type StatusCheckRollup} from '../../../types/routes-types'
import styles from './DashboardSection.module.css'

export const reviewDecision = (reviewDecisionState: ReviewDecisionState) => {
  let reviewDecisionIcon = null
  switch (reviewDecisionState) {
    case ReviewDecisionState.Approved:
      reviewDecisionIcon = (
        <span>
          <CheckCircleFillIcon size={12} className="color-fg-success" /> <span>Approved</span>
        </span>
      )
      break
    case ReviewDecisionState.ChangesRequested:
      reviewDecisionIcon = (
        <span>
          <XCircleFillIcon size={12} className="color-fg-danger" /> <span>Changes requested</span>
        </span>
      )
      break
    case ReviewDecisionState.ReviewRequired:
      reviewDecisionIcon = (
        <span>
          <NoEntryFillIcon size={12} className="color-fg-attention" /> <span>Review required</span>
        </span>
      )
      break
    default:
      return null
  }

  return (
    <span data-testid="review-decision-icon">
      <span className="mr-1 ml-1">&middot; </span>
      {reviewDecisionIcon}
    </span>
  )
}

export const statusCheckDisplay = (statusCheckRollup: StatusCheckRollup) => {
  let statusIcon = null
  switch (statusCheckRollup.state) {
    case StatusCheckState.Success:
      statusIcon = <CheckIcon size={12} className="color-fg-success" />
      break
    case StatusCheckState.Failure:
      statusIcon = <XIcon size={12} className="color-fg-danger" />
      break
    case StatusCheckState.Pending:
      statusIcon = <ClockIcon size={12} className="color-fg-attention" />
      break
    default:
      return null
  }

  return (
    <span data-testid="ci-status-check">
      <span className="mr-1 ml-1">&middot; </span>
      {statusIcon} {statusCheckRollup.successCount}/{statusCheckRollup.totalCount}
    </span>
  )
}

export const reviewDecisionCompact = (reviewDecisionState: ReviewDecisionState) => {
  let icon = null
  let label = ''
  switch (reviewDecisionState) {
    case ReviewDecisionState.Approved:
      icon = <CheckCircleFillIcon size={16} className="color-fg-success" />
      label = 'Approved'
      break
    case ReviewDecisionState.ChangesRequested:
      icon = <FileDiffIcon size={16} className="color-fg-danger" />
      label = 'Changes requested'
      break
    case ReviewDecisionState.ReviewRequired:
      icon = <NoEntryFillIcon size={16} className="color-fg-attention" />
      label = 'Review required'
      break
    default:
      return null
  }

  return (
    <Tooltip text={label} direction="s" type="label">
      <button type="button" data-testid="review-decision-compact" className={styles.tooltipTrigger}>
        {icon}
      </button>
    </Tooltip>
  )
}

const statusCheckIcon = (state: StatusCheckState, size: number = 16) => {
  switch (state) {
    case StatusCheckState.Success:
      return <CheckIcon size={size} className="color-fg-success" />
    case StatusCheckState.Failure:
      return <XIcon size={size} className="color-fg-danger" />
    case StatusCheckState.Pending:
      return <ClockIcon size={size} className="color-fg-attention" />
    default:
      return null
  }
}

const statusCheckLabel = (statusCheckRollup: StatusCheckRollup) => {
  const action = statusCheckRollup.state === StatusCheckState.Pending ? 'pending' : 'passing'
  return `CI: ${statusCheckRollup.successCount}/${statusCheckRollup.totalCount} checks ${action}`
}

export const statusCheckDisplayCompact = (statusCheckRollup: StatusCheckRollup) => {
  const icon = statusCheckIcon(statusCheckRollup.state)
  if (!icon) return null

  return (
    <Tooltip text={statusCheckLabel(statusCheckRollup)} direction="s" type="label">
      <button type="button" data-testid="ci-status-compact" className={styles.tooltipTrigger}>
        {icon}
      </button>
    </Tooltip>
  )
}

export const statusCheckColumnDisplay = (statusCheckRollup: StatusCheckRollup) => {
  const icon = statusCheckIcon(statusCheckRollup.state)
  if (!icon) return null

  return (
    <span data-testid="ci-status-column" style={{display: 'inline-flex', alignItems: 'center', gap: '4px'}}>
      {icon} {statusCheckRollup.successCount}/{statusCheckRollup.totalCount}
    </span>
  )
}
