import {verifiedFetchJSON} from '@github-ui/verified-fetch'

const REPO_FILTER_PREFIX = 'repo:'

export type RepoOption = {name: string; enabled?: boolean; private?: boolean}

export type RepositorySuggestion = {
  name: string
  owner: string
  visibility: string
  nameWithOwner: string
}

export type ParsedInboxFilterQuery = {
  repos: string[]
}

export function uniqueTerms(terms: string[]): string[] {
  return Array.from(new Set(terms))
}

function tokenizeQuery(rawQuery: string): string[] {
  return rawQuery.trim().split(/\s+/).filter(Boolean)
}

export function uniqueByName<T extends {name: string}>(items: T[]): T[] {
  const seen = new Set<string>()
  return items.filter(item => {
    if (seen.has(item.name)) return false
    seen.add(item.name)
    return true
  })
}

export function includesCaseInsensitive(value: string, query: string): boolean {
  return value.toLowerCase().includes(query.trim().toLowerCase())
}

export async function fetchFilterSuggestions<T>(endpoint: string, query: string): Promise<T[]> {
  try {
    const searchParams = new URLSearchParams()
    searchParams.set('q', query)
    searchParams.set('filter_value', query)

    const response = await verifiedFetchJSON(`${endpoint}?${searchParams.toString()}`)

    if (!response.ok) return []

    const json = (await response.json()) as Record<string, unknown>
    const dataKey = Object.keys(json)[0]
    const suggestions = dataKey ? (json[dataKey] as T[]) : null

    return Array.isArray(suggestions) ? suggestions : []
  } catch {
    return []
  }
}

export function parseInboxFilterQuery(rawQuery: string): ParsedInboxFilterQuery {
  const repos: string[] = []

  for (const term of tokenizeQuery(rawQuery)) {
    const normalizedTerm = term.toLowerCase()

    if (normalizedTerm.startsWith(REPO_FILTER_PREFIX)) {
      const repo = term.slice(REPO_FILTER_PREFIX.length)
      if (repo) repos.push(repo)
      continue
    }
  }

  return {
    repos: uniqueTerms(repos),
  }
}

export function buildInboxFilterQuery({repos}: ParsedInboxFilterQuery): string {
  const terms = [...uniqueTerms(repos).map(repo => `${REPO_FILTER_PREFIX}${repo}`)]

  return terms.join(' ').trim()
}

export function repoOwnerFromTerm(repoNameWithOwner: string): string | undefined {
  return repoNameWithOwner.split('/')[0]
}
