import {useQuery} from '@github-ui/react-query'
import {useCallback, useEffect, useMemo, useState} from 'react'
import type {DeferredItem, EnrichedPull, PullItem, SectionDataResult} from '../types/routes-types'

const SECTION_STALE_TIME = 30_000 // 30 seconds
const LOAD_MORE_INCREMENT = 10
const MAX_SECTION_RESULTS = 25

interface UseSectionDataOptions {
  sectionId: string
  scopeKey: string
  primaryData: SectionDataResult | undefined
  isPrimaryPending: boolean
  isPrimaryError: boolean
  fetchDeferred?: (results: PullItem[]) => Promise<DeferredItem[]>
  maxItems: number
}

interface UseSectionDataResult {
  enrichedPulls: EnrichedPull[]
  totalCount: number
  hasMore: boolean
  isPending: boolean
  isError: boolean
  isDeferredError: boolean
  loadMore: () => void
}

export function useSectionData({
  sectionId,
  scopeKey,
  primaryData,
  isPrimaryPending,
  isPrimaryError,
  fetchDeferred,
  maxItems,
}: UseSectionDataOptions): UseSectionDataResult {
  const [visibleCount, setVisibleCount] = useState(() => maxItems)
  const [deferredCache, setDeferredCache] = useState<Map<number, DeferredItem>>(() => new Map())

  const primaryResults = useMemo(() => primaryData?.results ?? [], [primaryData?.results])
  const boundedVisibleCount = Math.min(visibleCount, MAX_SECTION_RESULTS)

  const visibleResults = useMemo(
    () => primaryResults.slice(0, boundedVisibleCount),
    [primaryResults, boundedVisibleCount],
  )
  const visibleResultIds = useMemo(() => visibleResults.map(result => result.id), [visibleResults])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- reset section progressive state when section scope changes
    setVisibleCount(maxItems)

    setDeferredCache(new Map())
  }, [maxItems, sectionId, scopeKey])

  const {data: deferredResults, isError: isDeferredError} = useQuery<DeferredItem[]>({
    // eslint-disable-next-line @tanstack/query/exhaustive-deps -- visibleResultIds captures the data dependency; fetchDeferred is stable
    queryKey: ['inbox-section-deferred', sectionId, visibleResultIds],
    queryFn: async () => {
      if (!fetchDeferred) return []

      const missingResults = visibleResults.filter(result => !deferredCache.has(result.id))

      if (missingResults.length > 0) {
        const fetchedDeferred = await fetchDeferred(missingResults)
        const nextCache = new Map(deferredCache)
        for (const item of fetchedDeferred) {
          nextCache.set(item.id, item)
        }
        return Array.from(nextCache.values())
      }

      return Array.from(deferredCache.values())
    },
    staleTime: SECTION_STALE_TIME,
    enabled: !!fetchDeferred && visibleResults.length > 0,
  })

  useEffect(() => {
    if (!deferredResults?.length) return

    // eslint-disable-next-line react-hooks/set-state-in-effect -- cache deferred payloads for incremental loading
    setDeferredCache(previous => {
      const next = new Map(previous)
      for (const item of deferredResults) {
        next.set(item.id, item)
      }
      return next
    })
  }, [deferredResults])

  const enrichedPulls = useMemo(() => {
    const deferredMap = new Map(deferredResults?.map(item => [item.id, item]) ?? [])

    return visibleResults.map(pull => {
      const deferred = deferredMap.get(pull.id)
      return {
        ...pull,
        reviewDecisionState: deferred?.reviewDecisionState,
        statusCheckRollup: deferred?.statusCheckRollup,
      }
    })
  }, [visibleResults, deferredResults])

  const loadMore = useCallback(() => {
    setVisibleCount(current => Math.min(current + LOAD_MORE_INCREMENT, MAX_SECTION_RESULTS))
  }, [])

  const hasMore =
    (primaryData?.totalCount ?? 0) > visibleResults.length && primaryResults.length > visibleResults.length

  return {
    enrichedPulls,
    totalCount: primaryData?.totalCount ?? 0,
    hasMore,
    isPending: isPrimaryPending,
    isError: isPrimaryError,
    isDeferredError,
    loadMore,
  }
}
