import type {SsoBannerResponse} from '@github-ui/global-sso-banner/types'
import type {SidebarLink} from '@github-ui/saved-views'

export interface PullsDashboardSurfacePayload {
  results: PullItem[]
  pageInfo: PageInfo
}

export interface PullsListResults {
  results: PullItem[]
  pageInfo: PageInfo
}

export const PullsInboxMaxAge = {
  OneMonth: '1m',
  ThreeMonths: '3m',
  OneYear: '1y',
  None: 'none',
} as const

export type PullsInboxMaxAge = (typeof PullsInboxMaxAge)[keyof typeof PullsInboxMaxAge]

export const PULLS_INBOX_MAX_AGE_LABELS: Record<PullsInboxMaxAge, string> = {
  [PullsInboxMaxAge.OneMonth]: 'Last month',
  [PullsInboxMaxAge.ThreeMonths]: 'Last 3 months',
  [PullsInboxMaxAge.OneYear]: 'Last year',
  [PullsInboxMaxAge.None]: 'Any time',
}

export interface InboxFilters {
  maxPrAge?: PullsInboxMaxAge
}

export interface PullsDashboardLayoutPayload {
  savedViews: SidebarLink[]
  sidebarLinks: SidebarLink[]
  compactMode?: boolean
  inboxSectionQueries?: Record<string, string>
  filters?: InboxFilters
  sso?: SsoBannerResponse
}

export interface PullsDashboardDeferredDataPayload {
  payload: {
    pullsDashboardSurfaceContentDeferredData: {
      results: DeferredItem[]
    }
  }
}

export interface PullsInboxDeferredDataPayload {
  payload: {
    pullsInboxSurfaceContentDeferredData: {
      results: DeferredItem[]
    }
  }
}

export interface PageInfo {
  currentPage: number
  totalPages: number
  totalCount: number
}

export const StateType = {
  Opened: 'OPEN',
  Closed: 'CLOSED',
  Merged: 'MERGED',
} as const

export type StateType = (typeof StateType)[keyof typeof StateType]

export const DisplayStateType = {
  Draft: 'DRAFT',
  Opened: 'OPEN',
  Closed: 'CLOSED',
  Merged: 'MERGED',
  Queued: 'QUEUED',
} as const

export type DisplayStateType = (typeof DisplayStateType)[keyof typeof DisplayStateType]

export interface Label {
  color?: string
  description?: string
  id: number
  name: string
  nameHtml?: string
}

export interface PullItem {
  author: {
    displayLogin: string
  }
  commentCount: number
  createdAt: string
  updatedAt: string
  displayState?: DisplayStateType
  headSha?: string
  labels: Label[]
  id: number
  isDraft: boolean
  number: number
  permalink: string
  isReadByCurrentUser: boolean
  repoNameWithOwner: string
  category?: DeferredCategory
  state: StateType
  title: string
  titleHtml?: string
}

export interface DeferredItem {
  id: number
  reviewDecisionState?: ReviewDecisionState
  statusCheckRollup?: StatusCheckRollup
}

export const DeferredCategory = {
  ChangesRequested: 'CHANGES_REQUESTED',
  CiFailing: 'CI_FAILING',
  ReadyToMerge: 'READY_TO_MERGE',
  AwaitingReview: 'AWAITING_REVIEW',
  MergeQueue: 'MERGE_QUEUE',
} as const

export type DeferredCategory = (typeof DeferredCategory)[keyof typeof DeferredCategory]

export interface StatusCheckRollup {
  state: StatusCheckState
  successCount: number
  totalCount: number
}

export const ReviewDecisionState = {
  Approved: 'APPROVED',
  ChangesRequested: 'CHANGES_REQUESTED',
  ReviewRequired: 'REVIEW_REQUIRED',
} as const

export type ReviewDecisionState = (typeof ReviewDecisionState)[keyof typeof ReviewDecisionState]

export const StatusCheckState = {
  Success: 'SUCCESS',
  Failure: 'FAILURE',
  Pending: 'PENDING',
} as const

export type StatusCheckState = (typeof StatusCheckState)[keyof typeof StatusCheckState]

export interface DashboardSectionConfig {
  id: string
  name: string
  maxItems: number
  href: string
}

export interface SectionDataResult {
  results: PullItem[]
  totalCount: number
}

export type EnrichedPull = PullItem & Partial<Omit<DeferredItem, 'id'>>

export interface PullsDashboardEnrichedDataPayload {
  pulls: EnrichedPull[]
  pageInfo: PageInfo
  isPending?: boolean
  isError?: boolean
}
