import type {SuppliedFilterProvider} from '@github-ui/filter-core'
import {ISSUE_TYPE_FILTER_KEY, type IssueTypeFilterProvider} from '@github-ui/issue-type-filter-provider'

export function isIssueTypeFilterProvider(
  filterProvider: SuppliedFilterProvider,
): filterProvider is IssueTypeFilterProvider {
  return 'displayName' in filterProvider && filterProvider.displayName === ISSUE_TYPE_FILTER_KEY.displayName
}
