import {isFeatureEnabled} from '@github-ui/feature-flags'
import {PULLS_INBOX_PATH, PULLS_PATH} from '../constants/routes'
const isInboxEnabled = () => {
  return isFeatureEnabled('pulls_dashboard_inbox')
}

export const isOnInboxPath = ({pathname}: {pathname: string}) => {
  if (!isInboxEnabled()) return false
  const normalized = pathname.length > 1 ? pathname.replace(/\/+$/, '') : pathname
  return normalized === PULLS_PATH || normalized === PULLS_INBOX_PATH
}
